def parse(tree):
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


def modeValuesInBst(tree):
    val, left, right = parse(tree)
    best, modes = 0, []
    cur, run = -1, 0
    stack = []
    u = 0
    while stack or u != -1:
        while u != -1:
            stack.append(u)
            u = left[u]
        u = stack.pop()
        x = val[u]
        if x == cur:
            run += 1
        else:
            cur, run = x, 1
        if run > best:
            best, modes = run, [x]
        elif run == best:
            modes.append(x)
        u = right[u]
    return modes
